import React from "react";
import { useDispatch } from "react-redux";
import { Link, useNavigate } from "react-router-dom";
import { logout } from "../Features/UserSlice";
import "../Styles/Header.css";

const Header = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // Logout function to clear user session and navigate to login
  const handleLogout = async () => {
    // Remove all saved session data
    localStorage.removeItem("role");
    localStorage.removeItem("loggedUser");
    localStorage.removeItem("applications");

    // Also reset Redux state
    dispatch(logout());

    // Small delay before navigation
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  return (
    <header className="header">
      {/* Left side - app logo and name */}
      <div className="brand">
        <div className="logo-circle">UL</div>
        <div className="brand-text">
          <span className="brand-main">UTAS</span>
          <span className="brand-accent">Link</span>
        </div>
      </div>

      {/* Right side - navigation links */}
      <nav className="nav-links">
        <Link to="/">Home</Link>

        {/* Student navigation links */}
        {role === "student" && (
          <>
            <Link to="/findjob">Find Job</Link>
            <Link to="/myapplications">My Applications</Link>
            <Link to="/userprofile">Profile</Link>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* Company navigation links */}
        {role === "company" && (
          <>
            <Link to="/companyprofile">Company Profile</Link>
            <Link to="/postjob">Post Job</Link>
            <Link to="/companyjobs">My Jobs</Link>
            <Link to="/applicantsjob">Applicants</Link>
            <Link to="/chatpage">Chat</Link>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* Guest navigation links (not logged in) */}
        {!role && (
          <>
            <Link to="/login">Login</Link>
            <Link to="/user-register">Register</Link>
          </>
        )}
      </nav>
    </header>
  );
};

export default Header;
